import { relay } from "./relay";
export { run as reexported } from "./reexport";

interface PkgApi {
  get(): (s: () => number) => void;
  pair(): { fn: (s: () => number) => void };
}
declare const api: PkgApi;

// Each export hands its parameter to a function value its source does not
// define; the same call written in the project is SC9011 (ADR 0370).
export function run(source: () => number): void {
  const fn = api.get();
  fn(source);
}

export function aliased(source: () => number): void {
  const held = source;
  const fn = api.get();
  fn(held);
}

export function destructured(source: () => number): void {
  const { fn } = api.pair();
  fn(source);
}

function getFn(): (s: () => number) => void {
  return api.get();
}

export function returned(source: () => number): void {
  const fn = getFn();
  fn(source);
}

export function chained(source: () => number): void {
  relay(source);
}

export function later(source: () => number): void {
  queueMicrotask(() => {
    const fn = api.get();
    fn(source);
  });
}

export const tools = {
  run(source: () => number): void {
    const fn = api.get();
    fn(source);
  },
};
